CREATE TABLE IF NOT EXISTS food_supplier (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL, contact VARCHAR(50) NOT NULL, phone VARCHAR(30) NOT NULL, active TINYINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS food_store (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL, contact VARCHAR(50) NOT NULL, phone VARCHAR(30) NOT NULL, address VARCHAR(300) NOT NULL, supplier_id BIGINT, active TINYINT NOT NULL DEFAULT 1, FOREIGN KEY (supplier_id) REFERENCES food_supplier(id));
CREATE TABLE IF NOT EXISTS food_product (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL, category VARCHAR(40) NOT NULL, unit VARCHAR(15) NOT NULL, spec VARCHAR(80) NOT NULL, price DECIMAL(12,2) NOT NULL, minimum DECIMAL(12,2) NOT NULL DEFAULT 1, image VARCHAR(500) NOT NULL, description VARCHAR(500) NOT NULL, active TINYINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS food_account (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, name VARCHAR(80) NOT NULL, role VARCHAR(20) NOT NULL, store_id BIGINT, supplier_id BIGINT, active TINYINT NOT NULL DEFAULT 1, FOREIGN KEY (store_id) REFERENCES food_store(id), FOREIGN KEY (supplier_id) REFERENCES food_supplier(id));
CREATE TABLE IF NOT EXISTS food_session (token_hash CHAR(64) PRIMARY KEY, account_id BIGINT NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY (account_id) REFERENCES food_account(id));
CREATE TABLE IF NOT EXISTS food_cart (account_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity DECIMAL(12,2) NOT NULL, PRIMARY KEY (account_id,product_id), FOREIGN KEY (account_id) REFERENCES food_account(id), FOREIGN KEY (product_id) REFERENCES food_product(id));
CREATE TABLE IF NOT EXISTS food_order (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_no VARCHAR(50) NOT NULL UNIQUE, request_key VARCHAR(100) NOT NULL, account_id BIGINT NOT NULL, store_id BIGINT NOT NULL, supplier_id BIGINT NOT NULL, status VARCHAR(30) NOT NULL, previous_status VARCHAR(30), items_json LONGTEXT NOT NULL, total DECIMAL(14,2) NOT NULL, delivery_date DATE NOT NULL, delivery_slot VARCHAR(50) NOT NULL, contact VARCHAR(60) NOT NULL, phone VARCHAR(30) NOT NULL, address VARCHAR(300) NOT NULL, remark VARCHAR(500) NOT NULL, issue VARCHAR(500), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY request_account(account_id,request_key), INDEX supplier_status(supplier_id,status), INDEX store_created(store_id,created_at), FOREIGN KEY (store_id) REFERENCES food_store(id), FOREIGN KEY (supplier_id) REFERENCES food_supplier(id));
CREATE TABLE IF NOT EXISTS food_order_event (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, action VARCHAR(40) NOT NULL, note VARCHAR(500) NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY (order_id) REFERENCES food_order(id));
CREATE TABLE IF NOT EXISTS food_settlement (id BIGINT PRIMARY KEY AUTO_INCREMENT, store_id BIGINT NOT NULL, amount DECIMAL(14,2) NOT NULL, settlement_date DATE NOT NULL, note VARCHAR(500) NOT NULL, request_key VARCHAR(100) NOT NULL UNIQUE, actor_id BIGINT NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY (store_id) REFERENCES food_store(id));
CREATE TABLE IF NOT EXISTS food_allocation (settlement_id BIGINT NOT NULL, order_id BIGINT NOT NULL, amount DECIMAL(14,2) NOT NULL, PRIMARY KEY(settlement_id,order_id), FOREIGN KEY(settlement_id) REFERENCES food_settlement(id), FOREIGN KEY(order_id) REFERENCES food_order(id));
CREATE TABLE IF NOT EXISTS food_feedback (id BIGINT PRIMARY KEY AUTO_INCREMENT, account_id BIGINT NOT NULL, content VARCHAR(1000) NOT NULL, created_at DATETIME NOT NULL);
